1	//! Which props of a component evidence puts forward (ADR 0028, section A).
2	//!
3	//! [`decide`] is the one place the rules are combined: it takes the [`Evidence`] gathered for the members a
4	//! component's props type reaches and says, for each member, whether it is a typed row, a name in its collapsed
5	//! layer's `used` list, left in that layer, or unknown because the body says nothing. It is pure and total: no I/O, no
6	//! name lists, and its output follows the order of the members it is given.
7	//!
8	//! [`apply`] is its one caller, where a structural answer becomes output (`pipeline::revision`): the [`Inputs`]
9	//! gathered with the answer's resolution (so their reads are its dependencies) and the revision's call-site counts
10	//! (counted again each revision, so an edit to a consumer reaches every component it renders). The checker's merges
11	//! keep the inheritance layers, and so the `used` lists, of the structural answer.
12	
13	pub(crate) mod call_sites;
14	pub(crate) mod forwarding;
15	pub(crate) mod props_type;
16	
17	use std::collections::BTreeSet;
18	
19	use crate::types::output::ComponentEntry;
20	
21	/// The evidence about one component gathered with its resolution: what its props type writes and what its body does.
22	#[derive(Debug, Clone, PartialEq, Eq)]
23	pub(crate) struct Inputs {
24	    /// The component's place in the project, which its call-site count is looked up by.
25	    pub(crate) site: call_sites::SiteKey,
26	    /// What the props type writes itself.
27	    pub(crate) props_type: props_type::PropsType,
28	    /// What the component's body does with its props; `None` when it has no function of its own.
29	    pub(crate) body: Option<Body>,
30	}
31	
32	/// Decides where each member of `entry`'s props goes, from `inputs`, the revision's `call_sites` of the component and
33	/// the members its listed props and layers reach, and writes each collapsed layer's `used` list: the members of that
34	/// layer evidence names. Which props are listed or collapsed does not change.
35	pub(crate) fn apply(entry: &mut ComponentEntry, inputs: &Inputs, call_sites: &CallSites) {
36	    let rows = entry.props.values().chain(entry.notable_inherited.values()).map(AsRef::as_ref);
37	    let members = props_type::members(&inputs.props_type, rows, &entry.inheritance);
38	    let shown = decide(&Evidence { members: &members, body: inputs.body.as_ref(), call_sites });
39	    // A collapsed ambient member the signature defaults (`{ className = 'x' }`) is read by the body, which a row does
40	    // not record for a name left in its layer: it is `used` too. Nothing else in `rows` is added.
41	    let defaulted =
42	        members.iter().filter(|member| member.ambient && member.default_tag).map(|member| member.name.as_str());
43	    let used: BTreeSet<&str> = shown.used.iter().map(String::as_str).chain(defaulted).collect();
44	    for layer in &mut entry.inheritance {
45	        layer.used = layer.members.iter().filter(|name| used.contains(name.as_str())).cloned().collect();
46	    }
47	}
48	
49	/// Everything known about the members one component's props type reaches.
50	#[derive(Debug, Clone, Copy)]
51	pub(crate) struct Evidence<'a> {
52	    /// The members, in the order the props type reaches them; [`Shown`] keeps this order. A name repeated is placed
53	    /// once, by its first member.
54	    pub(crate) members: &'a [Member],
55	    /// What the component's own function body does with its props; `None` when it has no function of its own.
56	    pub(crate) body: Option<&'a Body>,
57	    /// The props passed at the component's JSX call sites across the project.
58	    pub(crate) call_sites: &'a CallSites,
59	}
60	
61	/// One member the props type reaches, with the signals its declaration gives.
62	#[derive(Debug, Clone, Default, PartialEq, Eq)]
63	pub(crate) struct Member {
64	    /// The member's name. Only compared with other names in the same [`Evidence`], never with a list.
65	    pub(crate) name: String,
66	    /// The props type declares it itself, not through an inherited source.
67	    pub(crate) own: bool,
68	    /// A key a `Pick<X, …>` names.
69	    pub(crate) picked: bool,
70	    /// It redeclares or narrows a base member.
71	    pub(crate) overrides: bool,
72	    /// It is not optional.
73	    pub(crate) required: bool,
74	    /// Its declaration carries a `@default` tag.
75	    pub(crate) default_tag: bool,
76	    /// It carries a JSDoc comment: orders the rows, never shows a member.
77	    pub(crate) documented: bool,
78	    /// Its type is a union of literals: orders the rows, never shows a member.
79	    pub(crate) literal_union: bool,
80	    /// Declared by React's or the shared DOM declarations ([`crate::origin::Origin::is_ambient`]): decided by
81	    /// the declaring path, never by the name.
82	    pub(crate) ambient: bool,
83	}
84	
85	/// What a component's function body does with its props, read from the syntax alone.
86	#[derive(Debug, Clone, Default, PartialEq, Eq)]
87	pub(crate) struct Body {
88	    /// The props the body reads. Complete only when [`Body::is_complete`].
89	    pub(crate) reads: Vec<String>,
90	    /// The JSX elements the body writes, in source order.
91	    pub(crate) elements: Vec<Element>,
92	    /// The props object or a rest binding escapes in a way the syntax cannot follow: what the body says still holds,
93	    /// but its silence about a prop is unknown, never guessed.
94	    pub(crate) handed_on: bool,
95	}
96	
97	/// One JSX element a component body writes.
98	#[derive(Debug, Clone, PartialEq, Eq)]
99	pub(crate) struct Element {
100	    /// What the tag resolves to.
101	    pub(crate) target: Target,
102	    /// Its attributes in source order, so a named attribute's place before or after a spread is kept.
103	    pub(crate) attributes: Vec<Attribute>,
104	}
105	
106	/// What a JSX tag resolves to.
107	#[derive(Debug, Clone, PartialEq, Eq)]
108	pub(crate) enum Target {
109	    /// A host element: a spread onto it passes only ambient DOM attributes.
110	    Dom,
111	    /// A component resolved by symbol and import, with the names of its own non-ambient props.
112	    Component(Vec<String>),
113	    /// A component tag that did not resolve: a spread onto it leaves the body's evidence unknown.
114	    Unresolved,
115	}
116	
117	/// One attribute of a JSX element.
118	#[derive(Debug, Clone, PartialEq, Eq)]
119	pub(crate) enum Attribute {
120	    /// `name={value}`: set after a spread, it fixes `name`; its value adds nothing.
121	    Named(String),
122	    /// `{...value}`.
123	    Spread(SpreadOf),
124	}
125	
126	/// What a JSX spread attribute spreads.
127	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
128	pub(crate) enum SpreadOf {
129	    /// The props object, whole.
130	    Props,
131	    /// A rest binding of the props object.
132	    Rest,
133	    /// Any other expression: no evidence about the props.
134	    Other,
135	}
136	
137	/// How often each prop is passed at a component's JSX call sites.
138	#[derive(Debug, Clone, Default, PartialEq, Eq)]
139	pub(crate) struct CallSites {
140	    /// The number of call sites.
141	    pub(crate) sites: u32,
142	    /// Each prop passed at them, with the number of sites passing it.
143	    pub(crate) passed: Vec<(String, u32)>,
144	}
145	
146	/// No call sites: no evidence.
147	pub(crate) static NO_CALL_SITES: CallSites = CallSites { sites: 0, passed: Vec::new() };
148	
149	impl CallSites {
150	    /// Whether `count` of the sites reach the floor of `max(2, 20%)` of them.
151	    fn at_floor(&self, count: u32) -> bool {
152	        count >= 2 && u64::from(count) * 5 >= u64::from(self.sites)
153	    }
154	}
155	
156	/// Where [`decide`] puts each member, every list in the order of [`Evidence::members`], except that `rows` puts the
157	/// documented and literal-union members first.
158	#[derive(Debug, Clone, Default, PartialEq, Eq)]
159	pub(crate) struct Shown {
160	    /// Typed rows.
161	    pub(crate) rows: Vec<String>,
162	    /// Ambient members named in their collapsed layer's `used` list: passed at the floor or read.
163	    pub(crate) used: Vec<String>,
164	    /// Members left in their collapsed layer.
165	    pub(crate) collapsed: Vec<String>,
166	    /// Members with no signal whose body evidence is incomplete or absent: listed or collapsed by the collapse rule
167	    /// alone, so missing evidence never hides more than that rule does.
168	    pub(crate) unknown: Vec<String>,
169	}
170	
171	/// Decides, from the evidence alone, where each member of a component's props goes.
172	pub(crate) fn decide(evidence: &Evidence<'_>) -> Shown {
173	    let body = evidence.body;
174	    let complete = body.is_some_and(Body::is_complete);
175	    let reads: BTreeSet<&str> = body.map(|body| body.reads.iter().map(String::as_str).collect()).unwrap_or_default();
176	    let forwarded = body.map(Body::forwarded).unwrap_or_default();
177	    let passed: BTreeSet<&str> = evidence
178	        .call_sites
179	        .passed
180	        .iter()
181	        .filter(|(_, count)| evidence.call_sites.at_floor(*count))
182	        .map(|(name, _)| name.as_str())
183	        .collect();
184	    let mut shown = Shown::default();
185	    let mut ordered_rows = Vec::new();
186	    let mut placed = BTreeSet::new();
187	    for member in evidence.members {
188	        let name = member.name.as_str();
189	        if !placed.insert(name) {
190	            continue;
191	        }
192	        let declared = member.own || member.picked || member.overrides || member.required || member.default_tag;
193	        // Passed at the floor or read puts a member forward: a typed row unless ambient, then a name in its layer's
194	        // `used` list (ADR 0028, Combination).
195	        let wanted = passed.contains(name) || reads.contains(name);
196	        let list = if declared || (!member.ambient && (wanted || forwarded.contains(name))) {
197	            ordered_rows.push((!(member.documented || member.literal_union), member.name.clone()));
198	            continue;
199	        } else if member.ambient && wanted {
200	            &mut shown.used
201	        } else if !complete {
202	            &mut shown.unknown
203	        } else {
204	            &mut shown.collapsed
205	        };
206	        list.push(member.name.clone());
207	    }
208	    ordered_rows.sort_by_key(|(plain, _)| *plain);
209	    shown.rows = ordered_rows.into_iter().map(|(_, name)| name).collect();
210	    shown
211	}
212	
213	impl Body {
214	    /// Whether the body's evidence is complete, so that a prop it never mentions is known to be unused: nothing handed
215	    /// on, and no spread of the props onto a tag that did not resolve. What an incomplete body does say (a read, a
216	    /// default, a forward) is still certain; only its silence is unknown.
217	    fn is_complete(&self) -> bool {
218	        !self.handed_on
219	            && !self.elements.iter().any(|element| {
220	                element.target == Target::Unresolved
221	                    && element.attributes.iter().any(|attribute| attribute.spreads_props())
222	            })
223	    }
224	
225	    /// The props a spread of the props object or a rest binding passes one hop on to a component: the component's own
226	    /// props, minus those an attribute after the spread fixes. Spreads onto DOM tags pass nothing.
227	    fn forwarded(&self) -> BTreeSet<&str> {
228	        let mut forwarded = BTreeSet::new();
229	        for element in &self.elements {
230	            let Target::Component(own) = &element.target else { continue };
231	            for (at, attribute) in element.attributes.iter().enumerate() {
232	                if !attribute.spreads_props() {
233	                    continue;
234	                }
235	                let fixed: BTreeSet<&str> = element.attributes[at + 1..]
236	                    .iter()
237	                    .filter_map(|after| match after {
238	                        Attribute::Named(name) => Some(name.as_str()),
239	                        Attribute::Spread(_) => None,
240	                    })
241	                    .collect();
242	                forwarded.extend(own.iter().map(String::as_str).filter(|name| !fixed.contains(name)));
243	            }
244	        }
245	        forwarded
246	    }
247	}
248	
249	impl Attribute {
250	    /// Whether the attribute spreads the props object or a rest binding of it.
251	    fn spreads_props(&self) -> bool {
252	        matches!(self, Self::Spread(SpreadOf::Props | SpreadOf::Rest))
253	    }
254	}
